package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.client.RestClient;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import java.net.http.HttpClient;
import java.time.Duration;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import tools.jackson.databind.ObjectMapper;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;
import static com.greatleyposhley.professy.collaboration.DeliveryRules.*;
/** Ticket description is the task; the spec supplies bounded execution metadata. */
@RestController @RequestMapping("/api/tickets/{kind}/{ticketId}/execution")
public class TicketExecution {
 final WorkAccess access;final ObjectMapper json;final WorkspaceAgents agents;final HttpServletRequest request;
 static RestClient localClient(String url){
  var factory=new JdkClientHttpRequestFactory(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build());
  factory.setReadTimeout(Duration.ofSeconds(15));
  return RestClient.builder().baseUrl(url).requestFactory(factory).build();
 }
 final RestClient forge=localClient("http://127.0.0.1:8093");
 final RestClient instru=localClient("http://127.0.0.1:8094");
 public TicketExecution(WorkAccess access,ObjectMapper json,WorkspaceAgents agents,HttpServletRequest request){this.access=access;this.json=json;this.agents=agents;this.request=request;}
 long org(){return access.actor().getOrgId();}
 static String supported(String kind){if(!Set.of("EPIC","STORY","TASK","ISSUE").contains(kind))throw new IllegalArgumentException("Choose an epic, story, task or issue");return kind;}
 Map<String,Object> spec(String kind,long id){var rows=access.jdbc.queryForList("SELECT spec_json,revision FROM ticket_execution_specs WHERE org_id=? AND ticket_kind=? AND ticket_id=?",org(),kind,id);if(rows.isEmpty())return Map.of("revision",0,"spec",Map.of());var row=rows.getFirst();return Map.of("revision",row.get("revision"),"spec",json.readValue(row.get("spec_json").toString(),Map.class));}
 @GetMapping public Object get(@PathVariable String kind,@PathVariable long ticketId){kind=supported(access.kind(kind));var ticket=access.ticket(kind,ticketId,false);return Map.of("ticket",Map.of("title",Objects.toString(ticket.get("title"),""),"description",Objects.toString(ticket.get("description"),""),"projectId",number(ticket.get("work_project_id"))),"configuration",spec(kind,ticketId),"runs",runs(kind,ticketId),"agent",assigned(kind,ticketId,(Map<String,Object>)spec(kind,ticketId).get("spec")),"skillCatalog",RuntimeSkills.CATALOG);}
 List<Map<String,Object>> runs(String kind,long id){var rows=access.jdbc.queryForList("SELECT j.*,a.display_name AS agentName FROM delivery_jobs j JOIN workspace_actors a ON a.id=j.agent_id WHERE j.org_id=? AND j.ticket_kind=? AND j.ticket_id=? ORDER BY j.created_at DESC LIMIT 30",org(),kind,id);for(var row:rows){row.remove("lease_token");if(row.get("result_json")!=null)row.put("result",json.readValue(row.remove("result_json").toString(),Map.class));}for(var row:rows){var contexts=access.jdbc.queryForList("SELECT context_json FROM ticket_execution_context WHERE job_id=?",row.get("id"));if(!contexts.isEmpty()){var context=new LinkedHashMap<String,Object>(json.readValue(contexts.getFirst().get("context_json").toString(),Map.class));if(context.get("snapshot") instanceof Map<?,?> snapshot)context.put("snapshot",Map.of("repositoryName",Objects.toString(snapshot.get("repositoryName"),""),"baseSha",Objects.toString(snapshot.get("baseSha"),"")));context.remove("infrastructure");context.remove("resourceCatalog");row.put("execution",context);}}return rows;}
 Map<String,Object> assigned(String kind,long id,Map<String,Object> spec){
  var rows=access.jdbc.queryForList("SELECT w.id,w.display_name AS name,c.enabled,c.worker_hash,c.skills_json,c.model FROM ticket_actor_assignments a JOIN workspace_actors w ON w.id=a.actor_id LEFT JOIN delivery_agent_config c ON c.agent_id=w.id WHERE a.org_id=? AND a.ticket_type=? AND a.ticket_id=? AND a.assignment_role='ASSIGNEE'",org(),kind,id);
  if(rows.isEmpty())return Map.of();var row=rows.getFirst();long agent=number(row.get("id"));var defaults=RuntimeSkills.defaults(access.jdbc,json,org(),agent);var effective=new LinkedHashMap<String,Object>(defaults);effective.putAll(spec);var required=RuntimeSkills.required(effective.get("requiredSkills"),Objects.toString(effective.get("testProfile"),"PYTHON_UNITTEST"));return Map.of("id",agent,"name",row.get("name"),"defaults",defaults,"readiness",RuntimeSkills.readiness(row,RuntimeSkills.report(access.jdbc,json,org(),agent),required,json));
 }
 @GetMapping("/runs/{runId}/events") public Object events(@PathVariable String kind,@PathVariable long ticketId,@PathVariable String runId,@RequestParam(defaultValue="0")long after){
  kind=supported(access.kind(kind));access.ticket(kind,ticketId,false);if(after<0)throw new IllegalArgumentException("Invalid event cursor");if(access.jdbc.queryForObject("SELECT COUNT(*) FROM delivery_jobs WHERE org_id=? AND ticket_kind=? AND ticket_id=? AND id=?",Integer.class,org(),kind,ticketId,runId)!=1)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Run not found");var rows=access.jdbc.queryForList("SELECT id,event,message,occurred_at AS occurredAt,received_at AS receivedAt FROM delivery_job_events WHERE org_id=? AND job_id=? AND id>? ORDER BY id LIMIT 200",org(),runId,after);return Map.of("items",rows,"cursor",rows.isEmpty()?after:rows.getLast().get("id"),"hasMore",rows.size()==200);
 }
 public static Map<String,Object> validate(Map<String,Object>b){var s=new LinkedHashMap<String,Object>();s.put("repositoryId",number(b.get("repositoryId")));if(number(s.get("repositoryId"))<1)throw new IllegalArgumentException("Choose a Forge repository");String branch=required(b.get("baseBranch"),120);if(!branch.matches("[A-Za-z0-9_./-]+")||branch.startsWith("-")||branch.contains(".."))throw new IllegalArgumentException("Invalid base branch");s.put("baseBranch",branch);s.put("testProfile",choice(b.get("testProfile"),Set.of("PYTHON_UNITTEST","NODE_TEST")));s.put("requiredSkills",RuntimeSkills.required(b.get("requiredSkills"),s.get("testProfile").toString()));s.put("testDirectory",".".equals(b.get("testDirectory"))?".":safePath(b.getOrDefault("testDirectory","tests")));s.put("acceptanceCriteria",required(b.get("acceptanceCriteria"),6000));String serviceId=text(b.get("serviceId"),36);if(!serviceId.isBlank())UUID.fromString(serviceId);s.put("serviceId",serviceId);s.put("serviceName",text(b.get("serviceName"),160));Object paths=b.get("allowedPaths");if(!(paths instanceof List<?> list)||list.isEmpty()||list.size()>20)throw new IllegalArgumentException("Specify 1–20 editable file paths or directories");s.put("allowedPaths",((List<?>)paths).stream().map(TicketExecution::safePath).distinct().toList());return s;}
 static String safePath(Object value){String p=required(value,180);if(p.startsWith("/")||p.contains("..")||!p.matches("[A-Za-z0-9_./-]+")||p.startsWith(".git")||p.contains("/.git")||p.equals("."))throw new IllegalArgumentException("Use a relative source or test path");return p;}
 @PutMapping @Transactional public Object save(@PathVariable String kind,@PathVariable long ticketId,@RequestBody Map<String,Object>b){kind=supported(access.kind(kind));var ticket=access.ticket(kind,ticketId,true);var s=validate((Map<String,Object>)b.getOrDefault("spec",Map.of()));long revision=number(b.get("revision"));var old=access.jdbc.queryForList("SELECT revision FROM ticket_execution_specs WHERE org_id=? AND ticket_kind=? AND ticket_id=? FOR UPDATE",org(),kind,ticketId);if(old.isEmpty()){if(revision!=0)throw conflict();access.jdbc.update("INSERT INTO ticket_execution_specs(org_id,ticket_kind,ticket_id,project_id,spec_json,updated_by) VALUES(?,?,?,?,?,?)",org(),kind,ticketId,ticket.get("work_project_id"),json.writeValueAsString(s),access.actor().getId());}else if(access.jdbc.update("UPDATE ticket_execution_specs SET spec_json=?,revision=revision+1,updated_by=?,updated_at=CURRENT_TIMESTAMP(6) WHERE org_id=? AND ticket_kind=? AND ticket_id=? AND revision=?",json.writeValueAsString(s),access.actor().getId(),org(),kind,ticketId,revision)!=1)throw conflict();return spec(kind,ticketId);}
 static ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"Execution settings changed; reload before saving");}
 @PostMapping("/runs") @Transactional public Object run(@PathVariable String kind,@PathVariable long ticketId){kind=supported(access.kind(kind));var ticket=access.ticket(kind,ticketId,true);var assignments=access.jdbc.queryForList("SELECT a.actor_id FROM ticket_actor_assignments a JOIN workspace_actors w ON w.id=a.actor_id JOIN workspace_agent_projects p ON p.actor_id=a.actor_id AND p.project_id=a.project_id WHERE a.org_id=? AND a.ticket_type=? AND a.ticket_id=? AND a.assignment_role='ASSIGNEE' AND w.status='ACTIVE' FOR UPDATE",org(),kind,ticketId);if(assignments.size()!=1)throw new IllegalArgumentException("Assign this ticket to one active project agent first");long agent=number(assignments.getFirst().get("actor_id"));var effective=(Map<?,?>)((Map<?,?>)agents.permissions(agent)).get("effective");if(!Boolean.TRUE.equals(effective.get("TICKETS.READ"))||!Boolean.TRUE.equals(effective.get("TICKETS.UPDATE")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Agent needs ticket read and update permissions");if(access.jdbc.queryForObject("SELECT COUNT(*) FROM delivery_agent_config WHERE agent_id=? AND org_id=? AND enabled=1 AND worker_hash IS NOT NULL",Integer.class,agent,org())!=1)throw new IllegalArgumentException("Enroll and enable the assigned agent's local worker");if(!access.jdbc.queryForList("SELECT id FROM delivery_jobs WHERE org_id=? AND ticket_kind=? AND ticket_id=? AND state IN ('QUEUED','RUNNING') FOR UPDATE",org(),kind,ticketId).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"A run is already active");var configuration=spec(kind,ticketId);var metadata=validate((Map<String,Object>)configuration.get("spec"));var readiness=(Map<?,?>)assigned(kind,ticketId,metadata).get("readiness");if(!Boolean.TRUE.equals(readiness.get("ready")))throw new ResponseStatusException(HttpStatus.CONFLICT,String.join("; ",(List<String>)readiness.get("reasons")));String description=required(ticket.get("description"),30000);Object snapshot;
 try{snapshot=forge.post().uri("/api/forge/repos/"+metadata.get("repositoryId")+"/execution-snapshot").header("Authorization",request.getHeader("Authorization")).contentType(org.springframework.http.MediaType.APPLICATION_JSON).body(json.writeValueAsBytes(metadata)).retrieve().body(Map.class);}catch(org.springframework.web.client.HttpStatusCodeException e){throw new ResponseStatusException(e.getStatusCode(),"Repository snapshot denied or exceeds the local execution limits");}catch(Exception e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Forge is unavailable; the run was not queued");}
 String id=UUID.randomUUID().toString().replace("-","");access.jdbc.update("INSERT INTO delivery_jobs(id,org_id,project_id,ticket_kind,ticket_id,service_id,agent_id,requested_by,title,instructions,workflow) VALUES(?,?,?,?,?,0,?,?,?,?, 'repository')",id,org(),ticket.get("work_project_id"),kind,ticketId,agent,access.actor().getId(),Objects.toString(ticket.get("title"),"Assigned ticket"),description);var context=new LinkedHashMap<String,Object>(metadata);context.put("snapshot",snapshot);if(!metadata.get("serviceId").toString().isBlank()){try{var resource=instru.get().uri("/api/instru/infrastructure/"+metadata.get("serviceId")).header("Authorization",request.getHeader("Authorization")).retrieve().body(Map.class);if(resource==null||number(resource.get("project_id"))!=number(ticket.get("work_project_id")))throw new IllegalArgumentException("Affected resource must belong to the ticket project");context.put("serviceName",resource.get("name"));var graph=instru.get().uri("/api/instru/architecture?projectId="+ticket.get("work_project_id")).header("Authorization",request.getHeader("Authorization")).retrieve().body(Map.class);context.put("infrastructure",graph);var resources=instru.get().uri("/api/instru/infrastructure?projectId="+ticket.get("work_project_id")).header("Authorization",request.getHeader("Authorization")).retrieve().body(List.class);context.put("resourceCatalog",resources==null?List.of():resources);}catch(org.springframework.web.client.RestClientException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Unable to verify the selected Instru resource");}}context.put("configurationRevision",configuration.get("revision"));context.put("ticketDescription",description);context.put("workerAtQueue",readiness.get("worker"));access.jdbc.update("INSERT INTO ticket_execution_context(job_id,context_json) VALUES(?,?)",id,json.writeValueAsString(context));access.jdbc.update("INSERT INTO delivery_job_events(org_id,job_id,worker_sequence,event,message,occurred_at) VALUES(?,?,-1,'QUEUED',?,?)",org(),id,"Ticket instructions, required skills and repository revision captured; waiting for the assigned worker.",java.time.Instant.now().toString());return Map.of("id",id,"state","QUEUED");}
}
